<?php
if(!defined('ABSPATH'))exit;
function dgs_teacher_url($args=array()){return dgs_school_url('education',dgs_edu_request_year(),array_merge(array('school_section'=>'teaching'),$args));}
function dgs_teacher_editor($uid=0){
 if(!current_user_can('dgs_manage_education'))return '';if($uid&&!dgs_edu_role($uid,'dgs_teacher'))return dgs_empty('حساب دبیر معتبر نیست.');$d=$uid?dgs_teacher_data($uid):array_fill_keys(array_keys(dgs_teacher_fields()),'');$out='<section class="dt-editor dsp-card"><div class="dsp-section-head"><h2>'.dgs_portal_icon('users').($uid?'ویرایش پرونده استاد':'افزودن استاد و تکمیل پرونده').'</h2><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_teacher_url()).'">بازگشت به دبیران</a></div><p>اطلاعات هویتی و تماس فقط برای مدیریت است. فقط بخش رزومه با انتخاب انتشار در سایت نمایش داده می‌شود. نام کاربری ثابت و رمز اولیه حساب جدید کد ملی است.</p><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'" class="dge-form"><input type="hidden" name="action" value="dgs_teacher_save"><input type="hidden" name="teacher_id" value="'.(int)$uid.'"><input type="hidden" name="revision" value="'.esc_attr($d['revision']??'').'">'.wp_nonce_field('dgs_teacher','dgs_teacher_nonce',true,false).'<h3>اطلاعات حساب و پرونده خصوصی</h3><div class="dge-grid">';
 foreach(array('full_name','national_id','phone','birth','address') as $key){$label=dgs_teacher_fields()[$key];$out.='<label>'.esc_html($label).(in_array($key,array('full_name','national_id','phone'),true)?' *':'').'<input name="'.$key.'" value="'.esc_attr($d[$key]).'" '.(in_array($key,array('full_name','national_id','phone'),true)?'required':'').' '.($key==='national_id'&&$uid&&$d[$key]!==''?'readonly':'').' maxlength="'.($key==='address'?500:100).'" '.($key==='birth'?'placeholder="1360-02-15"':'').'></label>';}
 $out.=dgs_edu_select('gender','جنسیت',array('male'=>'مرد','female'=>'زن'),$d['gender'],false).'</div><h3>رزومه عمومی استاد</h3><div class="dge-grid">';foreach(array('specialty','grades','teaching_years','video','portrait_id') as $key)$out.='<label>'.esc_html(dgs_teacher_fields()[$key]).'<input name="'.$key.'" value="'.esc_attr($d[$key]).'" '.(in_array($key,array('specialty','grades'),true)?'required':'').' '.($key==='grades'?'placeholder="10,11,12"':'').'></label>';
 $out.='<label>بارگذاری عکس استاد (JPG/PNG/WebP تا ۳ مگابایت)<input type="file" name="portrait" accept="image/jpeg,image/png,image/webp"></label></div>';
 foreach(array('bio','education','experience','skills') as $key)$out.='<label>'.esc_html(dgs_teacher_fields()[$key]).'<textarea name="'.$key.'" rows="3" maxlength="5000">'.esc_textarea($d[$key]).'</textarea></label>';
 $out.='<label class="dt-publish"><input type="checkbox" name="published" value="1" '.checked($d['published'],'1',false).'> رزومه عمومی این استاد در سایت منتشر شود (عکس، تخصص، پایه‌ها و سوابق)</label><button class="dg-btn">'.dgs_portal_icon('check').($uid?'ذخیره پرونده و رزومه':'ثبت استاد و ایجاد حساب').'</button></form></section>';return $out;
}
function dgs_teacher_manager($year){
 if(!current_user_can('dgs_manage_education'))return '';if(dgs_att_get('dt_add')==='1')return dgs_teacher_editor();$edit=absint(dgs_att_get('dt_edit'));if($edit)return dgs_teacher_editor($edit);
 $page=max(1,absint(dgs_att_get('dt_page','1')));$search=sanitize_text_field(dgs_att_get('dt_search'));$args=array('role'=>'dgs_teacher','number'=>20,'paged'=>$page,'orderby'=>'display_name','order'=>'ASC');if($search!==''){$args['search']='*'.$search.'*';$args['search_columns']=array('user_login','display_name');}$q=new WP_User_Query($args);
 $out='<section class="dsp-card dt-manager"><div class="dsp-section-head"><h3>'.dgs_portal_icon('users').' دبیران مدرسه</h3><div class="dsp-actions"><a class="dg-btn" href="'.esc_url(dgs_teacher_url(array('dt_add'=>1))).'">'.dgs_portal_icon('users').' افزودن دبیر</a><a class="dg-btn dg-btn-outline" href="'.esc_url(wp_nonce_url(add_query_arg('action','dgs_teacher_template',admin_url('admin-post.php')),'dgs_teacher_template')).'">'.dgs_portal_icon('download').' الگوی اکسل دبیران</a></div></div><form class="dge-filter" method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="education"><input type="hidden" name="school_section" value="teaching"><label>جست‌وجوی دبیر<input name="dt_search" value="'.esc_attr($search).'"></label><button class="dg-btn dg-btn-outline">جست‌وجو</button></form>'.dgs_edu_table_start(array('نام دبیر','شناسه اتصال','نام کاربری','تخصص','رزومه سایت','عملیات'));
 foreach($q->get_results() as $u){$post=(int)get_user_meta($u->ID,'_dgs_teacher_post',true);$data=dgs_teacher_data($u->ID);$out.='<tr><td>'.esc_html($u->display_name).'</td><td>'.(int)$u->ID.'</td><td dir="ltr">'.esc_html($u->user_login).'</td><td>'.esc_html($data['specialty']).'</td><td>'.($post&&get_post_status($post)==='publish'?'<a href="'.esc_url(get_permalink($post)).'">مشاهده رزومه منتشرشده</a>':'منتشر نشده').'</td><td><a class="dge-small-btn" href="'.esc_url(dgs_teacher_url(array('dt_edit'=>$u->ID))).'">تکمیل / ویرایش پرونده</a></td></tr>';}
 if(!$q->get_results())$out.='<tr><td colspan="6">دبیری پیدا نشد.</td></tr>';$out.='</tbody></table></div>';if($page>1)$out.='<a class="dge-small-btn" href="'.esc_url(dgs_teacher_url(array('dt_page'=>$page-1,'dt_search'=>$search))).'">قبلی</a>';if($page*20<$q->get_total())$out.='<a class="dge-small-btn" href="'.esc_url(dgs_teacher_url(array('dt_page'=>$page+1,'dt_search'=>$search))).'">بعدی</a>';
 $out.='<details><summary>ورود گروهی اکسل دبیران</summary><p>ستون‌های الگو تغییر نکنند. هر بار حداکثر ۱۰۰ دبیر جدید؛ حساب موجود بازنویسی نمی‌شود. published=1 رزومه را عمومی می‌کند؛ در حالت صفر پیش‌نویس است. عکس با شناسه رسانه وارد می‌شود یا بعداً از ویرایش بارگذاری کنید. کد ملی و موبایل به‌صورت متن با صفر ابتدایی ذخیره شوند.</p><form class="dge-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dgs_teacher_import">'.wp_nonce_field('dgs_teacher','dgs_teacher_nonce',true,false).'<label>فایل اکسل دبیران<input name="teacher_xlsx" type="file" accept=".xlsx" required></label><button class="dg-btn">ورود اکسل و ایجاد حساب‌ها</button></form><dl>';foreach(dgs_teacher_fields() as $key=>$label)$out.='<dt dir="ltr">'.$key.'</dt><dd>'.esc_html($label).'</dd>';return $out.'</dl></details></section>';
}
